{
  "lemma": "bend",
  "pos": "verb",
  "cefr": "B1",
  "definition_en": "To shape or force into a curve; to incline the body downward.",
  "explanation_ar": "إنك تتني حاجة وتخليها مقوسة، أو إنك تميل جسمك لتحت.",
  "senses": [
    {
      "definition_en": "To force something into a curved shape or become curved.",
      "definition_ar": "يثني شيئاً أو ينحني ليصبح مقوساً.",
      "examples": [
        "Can you bend this wire?"
      ]
    },
    {
      "definition_en": "To lean or curve your body or a part of it.",
      "definition_ar": "يحني جسمه أو يثني جزءاً منه كركبتيه أو ظهره.",
      "examples": [
        "Make sure to bend your knees when lifting heavy objects."
      ]
    },
    {
      "definition_en": "To modify or stretch rules or principles without strictly breaking them.",
      "definition_ar": "يتساهل في القواعد أو يحوّرها لمصلحته.",
      "examples": [
        "He refused to bend the rules for anyone."
      ]
    }
  ],
  "examples": [
    "Can you bend this wire?",
    "Make sure to bend your knees when lifting heavy objects.",
    "He refused to bend the rules for anyone."
  ],
  "translations": [
    "يثني",
    "ينحني",
    "يلوي"
  ],
  "relations": {
    "synonyms": [
      "curve",
      "flex",
      "bow"
    ],
    "antonyms": [
      "straighten"
    ],
    "collocations": [
      "bend down",
      "bend over",
      "bend the rules",
      "bend your knees"
    ]
  },
  "mnemonic": "اربطها بـ 'Band'.. زي ما الـ 'Band' 'الرباط' ممكن تعمل له 'Bend' 'تثنيه'.",
  "phonetic_us": "bɛnd",
  "phonetic_uk": "bend",
  "syllables": "bend",
  "semantic_tags": [
    "Body",
    "Shape",
    "Movement"
  ],
  "ai_confidence": 0.96
}

{
  "lemma": "thick",
  "pos": "adj",
  "cefr": "A2",
  "definition_en": "With opposite sides or surfaces that are a great distance apart; not thin.",
  "explanation_ar": "تخين أو سميك.. عكس رفيع. ممكن توصف كتاب، حيطة، أو حتى سائل تقيل.",
  "senses": [
    {
      "definition_en": "Having a large distance between opposite surfaces; not thin.",
      "definition_ar": "سميك، ذو سُمك كبير (عكس رفيع)",
      "examples": [
        "This book is very thick.",
        "The walls are thick to keep the house warm."
      ]
    },
    {
      "definition_en": "Growing or existing closely together; dense.",
      "definition_ar": "كثيف (مثل الضباب أو الشعر)",
      "examples": [
        "The fog was so thick we couldn't see."
      ]
    }
  ],
  "examples": [
    "This book is very thick.",
    "The walls are thick to keep the house warm.",
    "The fog was so thick we couldn't see."
  ],
  "translations": [
    "سميك",
    "كثيف"
  ],
  "relations": {
    "synonyms": [
      "dense",
      "heavy",
      "chunky"
    ],
    "antonyms": [
      "thin",
      "fine"
    ],
    "collocations": [
      "thick hair",
      "thick fog"
    ]
  },
  "mnemonic": "كلمة 'Thick' قريبة من 'Stick' 'عصاية'.. العصاية ممكن تكون 'Thick'.",
  "phonetic_us": "θɪk",
  "phonetic_uk": "θɪk",
  "syllables": [
    "thick"
  ],
